function medicalProviderRows(){return (rows.marketing_provider_profiles||[]).filter(p=>String(p.status||'').toUpperCase()==='ACTIVE' && p.is_verified===true && ['HEALTH','DENTAL','MEDICAL','VETERINARY'].includes(String(p.provider_kind||'').toUpperCase()) && Array.isArray(p.specialties) && p.specialties.some(s=>/طب|طبي|كشف|أسنان|صيدل|تحاليل|أشعة|مستشفى|طوارئ/.test(String(s))));}
function medicalStatusActions(a){
 const role=String(membership?.role||'').toUpperCase(),status=String(a.status||'').toUpperCase();
 const provider=['SERVICE_PROVIDER','OWNER','BUSINESS_OWNER','ADMIN','MANAGER'].includes(role);
 const due=Number(a.date_time)<=Date.now(),buttons=[];
 if(['BOOKED','CONFIRMED'].includes(status))buttons.push('<button class="btn btn-outline" type="button" data-medical-status="'+esc(a.id)+'" data-medical-target="CANCELLED">إلغاء</button>');
 if(status==='BOOKED'&&provider)buttons.push('<button class="btn btn-primary" type="button" data-medical-status="'+esc(a.id)+'" data-medical-target="CONFIRMED">تأكيد</button>');
 if(status==='CONFIRMED'&&provider&&due){
  buttons.push('<button class="btn btn-primary" type="button" data-medical-status="'+esc(a.id)+'" data-medical-target="COMPLETED">إكمال الزيارة</button>');
  buttons.push('<button class="btn btn-outline" type="button" data-medical-status="'+esc(a.id)+'" data-medical-target="NO_SHOW">لم يحضر</button>');
 }
 return buttons.length?'<div class="action-bar" style="gap:6px;flex-wrap:wrap">'+buttons.join('')+'</div>':'—';
}
